            name = self.advance()
            if name.kind != "IDENT":
                raise SyntaxError(f"expected identifier after 'let', got {name}")
            self.expect_op("=")
            value = self.expr()
            if not self._is("KW", "in"):
                raise SyntaxError(f"expected 'in', got {self.peek()}")
            self.advance()
            body = self.expr()
            return ("let", name.value, value, body)
        return self.or_expr()

